OM_uint32 spnego_gss_init_ctx_reselect(
    OM_uint32 *minor_status,
    spnego_gss_ctx_id_t sc,
    OM_uint32 acc_negState,
    gss_OID supportedMech,
    gss_buffer_t *responseToken,
    gss_buffer_t *mechListMIC,
    OM_uint32 *negState,
    send_token_flag *tokflag)
{
    OM_uint32 major_status;
    gss_OID_set temp_set = GSS_C_NO_OID_SET;

    // Delete the current context
    gss_delete_sec_context(&minor_status, &sc, GSS_C_NO_BUFFER);

    // Initialize the new context with the supported mechanism
    major_status = gss_init_sec_context(
        minor_status,
        GSS_C_NO_CREDENTIAL,
        &sc,
        supportedMech,
        GSS_C_MUTUAL_FLAG | GSS_C_REPLAY_FLAG | GSS_C_SEQUENCE_FLAG,
        GSS_C_INDEFINITE,
        GSS_C_NO_CHANNEL_BINDINGS,
        NULL,
        NULL,
        NULL,
        NULL,
        NULL,
        NULL);

    if (major_status != GSS_S_COMPLETE && major_status != GSS_S_CONTINUE_NEEDED) {
        // Handle error case
        return GSS_FAILURE;
    }

    // Set the accepted negotiation state
    *negState = acc_negState;

    // Set the token flag to indicate the token needs to be sent
    *tokflag = SEND_TOKEN_FLAG_INITIATOR;

    return GSS_S_COMPLETE;
}

OM_uint32 spnego_init_reselect_context(
    OM_uint32 *minor_status,
    spnego_gss_ctx_id_t sc,
    OM_uint32 acc_negState,
    gss_OID supportedMech,
    gss_buffer_t *responseToken,
    gss_buffer_t *mechListMIC,
    OM_uint32 *negState,
    send_token_flag *tokflag)
{
    OM_uint32 major_status;

    /* Delete current security context */
    (void)gss_delete_sec_context(minor_status, &sc->internal_context, NULL);

    /* Check if the supported mechanism is in the mechanism set */
    if (!gss_oid_equal(supportedMech, sc->supported_mech)) {
        *minor_status = GSS_S_BAD_MECH;
        return GSS_S_FAILURE;
    }

    /* Validate the negotiation state */
    if (acc_negState != sc->expected_negState) {
        *minor_status = GSS_S_BAD_SIG;
        return GSS_S_FAILURE;
    }

    /* Set the internal mechanism */
    sc->current_mech = supportedMech;

    /* Update the negotiation state */
    *negState = GSS_C_NEXT_STATE;

    /* Update the token send flag */
    *tokflag = SEND_TOKEN_FLAG;

    return GSS_S_COMPLETE;
}

OM_uint32 spnego_init_context_reselection(OM_uint32 *minor_status,
                                          spnego_gss_ctx_id_t sc,
                                          OM_uint32 acc_negState,
                                          gss_OID supportedMech,
                                          gss_buffer_t *responseToken,
                                          gss_buffer_t *mechListMIC,
                                          OM_uint32 *negState,
                                          send_token_flag *tokflag) {
    OM_uint32 major_status;
    OM_uint32 ret;

    /* Delete the current security context */
    if (sc != NULL) {
        (void)gss_delete_sec_context(&minor_status, &sc, NULL);
    }

    /* Check if the supported mechanism is in the mechanism set */
    if (supportedMech == GSS_C_NO_OID) {
        *minor_status = SPNEGO_BAD_MECHANISM;
        return GSS_S_BAD_MECH;
    }

    /* Validate the negotiation state */
    if (acc_negState != SPNEGO_NEG_STATE_ACCEPT_COMPLETED &&
        acc_negState != SPNEGO_NEG_STATE_ACCEPT_IN_PROGRESS) {
        *minor_status = SPNEGO_BAD_NEG_STATE;
        return GSS_S_FAILURE;
    }

    /* Set the internal mechanism */
    sc->internal_mech = supportedMech;

    /* Update the negotiation state and token flag */
    *negState = acc_negState;
    *tokflag = SEND_TOKEN_FLAG_SEND;

    ret = GSS_S_COMPLETE;

    return ret;
}

OM_uint32 spnego_gss_context_res_init(OM_uint32 *minor_status,
                                      spnego_gss_ctx_id_t sc,
                                      OM_uint32 acc_negState,
                                      gss_OID supportedMech,
                                      gss_buffer_t *responseToken,
                                      gss_buffer_t *mechListMIC,
                                      OM_uint32 *negState,
                                      send_token_flag *tokflag) {
    OM_uint32 major_status;

    if (minor_status)
        *minor_status = 0;

    if (!sc || !supportedMech || !responseToken || !negState || !tokflag)
        return GSS_S_BAD_ARG;

    if (acc_negState != GSS_C_NT_ACCEPT) {
        if (minor_status)
            *minor_status = EINVAL;
        return GSS_S_BAD_BINDINGS;
    }

    /* Delete the current security context */
    gss_delete_sec_context(&major_status, NULL, sc);
    if (major_status != GSS_S_COMPLETE) {
        if (minor_status)
            *minor_status = major_status;
        return GSS_S_FAILURE;
    }

    /* Check if the supported mechanism is supported */
    if (!gss_test_oid_equal(supportedMech, &gss_mech_spnego)) {
        if (minor_status)
            *minor_status = ENOTSUP;
        return GSS_S_BAD_MECH;
    }

    /* Validate negotiation state and update internal state */
    *negState = GSS_C_NT_ACCEPTED;
    *tokflag = SEND_TOKEN_FLAG;

    return GSS_S_COMPLETE;
}

OM_uint32 spnego_gss_context_reselect(
    OM_uint32 *minor_status,
    spnego_gss_ctx_id_t sc,
    OM_uint32 acc_negState,
    gss_OID supportedMech,
    gss_buffer_t *responseToken,
    gss_buffer_t *mechListMIC,
    OM_uint32 *negState,
    send_token_flag *tokflag)
{
    OM_uint32 major_status;

    if (minor_status) {
        *minor_status = 0;
    }

    if (!sc || !supportedMech || !negState || !tokflag) {
        return GSS_S_FAILURE;
    }

    /* Delete the current security context */
    gss_delete_sec_context(&major_status, NULL, sc);

    if (major_status != GSS_S_COMPLETE) {
        return major_status;
    }

    /* Check if the supported mechanism is valid */
    if (gss_oid_equal(supportedMech, GSS_C_NULL_OID)) {
        return GSS_S_BAD_MECH;
    }

    /* Validate the negotiation state */
    if (acc_negState != SPNEGO_NEG_STATE_ACCEPTED) {
        return GSS_S_BAD_SIG;
    }

    /* Set the internal mechanism */
    sc->mech_oid = supportedMech;

    /* Update the negotiation state */
    *negState = SPNEGO_NEG_STATE_SELECTED;

    /* Set the token send flag */
    *tokflag = SEND_TOKEN_FLAG_CONTINUE;

    return GSS_S_COMPLETE;
}
